const rows = $input.all();
const SLOTS_PER_DAY = 3;
const DAYS_TO_QUEUE = 1;
const SLOTS_PER_RUN = SLOTS_PER_DAY * DAYS_TO_QUEUE;

function firstText(...values) {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
}

function splitUrls(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(String).map(v => v.trim()).filter(Boolean);
  return String(value).split(/\n|,/).map(v => v.trim()).filter(Boolean);
}

function uniqueHttpUrls(values) {
  const seen = new Set();
  return values
    .filter(Boolean)
    .map(String)
    .map(v => v.trim())
    .filter(v => /^https?:\/\//i.test(v))
    .filter(v => seen.has(v) ? false : seen.add(v));
}

function orderedProductImages(row) {
  // Canonical sequence: primary image, then gallery_image_1..5.
  const canonical = uniqueHttpUrls([
    firstText(row.primary_image, row.image_url, row.image, row.featured_image, row.product_image, row.thumbnail_url),
    firstText(row.gallery_image_1),
    firstText(row.gallery_image_2),
    firstText(row.gallery_image_3),
    firstText(row.gallery_image_4),
    firstText(row.gallery_image_5),
  ]);
  if (canonical.length) return canonical;

  // Fallback only for rows that do not have the canonical six image columns.
  return uniqueHttpUrls([
    firstText(row.pin_image_url),
    ...splitUrls(row.gallery_images),
    ...splitUrls(row.images),
  ]);
}

// Sort by priority then row number. This determines the sequential product posting order.
const sortedRows = [...rows].sort((a, b) => {
  const aRow = a.json || {};
  const bRow = b.json || {};
  const aPriority = Number(aRow.pin_priority || aRow.priority || 999);
  const bPriority = Number(bRow.pin_priority || bRow.priority || 999);
  if (aPriority !== bPriority) return aPriority - bPriority;
  const aNum = Number(aRow.row_number || aRow.__rowNumber || aRow.rowNumber || 9999);
  const bNum = Number(bRow.row_number || bRow.__rowNumber || bRow.rowNumber || 9999);
  return aNum - bNum;
});

const batch = [];
let slotsRemaining = SLOTS_PER_RUN;

sortedRows.forEach((item, index) => {
  if (slotsRemaining <= 0) return;

  const row = item.json || {};
  const status = firstText(row.pin_status, row.pinterest_status, row.status).toLowerCase();
  if (['completed', 'skip'].includes(status)) return;

  const url = firstText(row.url, row.product_url, row.destination_url, row.canonical_url);
  if (!url) return;

  const allImages = orderedProductImages(row);
  if (!allImages.length) return;

  let publishedUrls = splitUrls(row.published_image_urls || '');

  // Backfill cursor for older runs: before published_image_urls existed, the workflow
  // wrote the last selected image into pin_image_url. Treat all images up to that one
  // as already used so the next run continues with the next gallery image.
  if (!publishedUrls.length && firstText(row.pin_image_url)) {
    const lastSelectedIndex = allImages.indexOf(firstText(row.pin_image_url));
    const hasPriorBufferPost = firstText(row.buffer_post_id, row.buffer_due_at, row.posted_at, row.last_attempt_at);
    if (lastSelectedIndex >= 0 && hasPriorBufferPost) {
      publishedUrls = allImages.slice(0, lastSelectedIndex + 1);
    }
  }

  const publishedSet = new Set(publishedUrls);
  const unpublished = allImages.filter(u => !publishedSet.has(u));
  if (!unpublished.length) return;

  const rowNumber = Number(row.row_number || row.__rowNumber || row.rowNumber || index + 2);

  // Drain this product first. With 3 slots/day, each daily run continues the current product before moving to the next.
  const toPost = unpublished.slice(0, slotsRemaining);
  toPost.forEach((imgUrl, imgIndex) => {
    const slotIndex = SLOTS_PER_RUN - slotsRemaining + imgIndex;
    const imageIndex = allImages.indexOf(imgUrl);
    batch.push({
      json: {
        ...row,
        row_number: rowNumber,
        has_pending: true,
        canonical_url: url,
        selected_image_url: imgUrl,
        selected_image_index: imageIndex,
        all_image_urls: allImages,
        images_total: allImages.length,
        images_remaining: unpublished.length - imgIndex,
        slot_index: slotIndex,
        attempt_count: Number(row.attempt_count || 0) + 1,
      }
    });
  });

  slotsRemaining -= toPost.length;
});

if (!batch.length) {
  return [{ json: { has_pending: false, message: 'No pending Pinterest rows with unpublished images.' } }];
}

return batch;

