const sources = $('Code - Build AI Request').all();
const responses = $input.all();

function cleanJson(text) {
  return String(text || '')
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
}

function truncate(text, max) {
  const value = String(text || '').replace(/\s+/g, ' ').trim();
  return value.length > max ? value.slice(0, max - 1).trimEnd() : value;
}

function parseAiContent(rawContent) {
  if (!rawContent || !rawContent.trim()) return {};
  const cleaned = cleanJson(rawContent);
  try {
    const parsed = JSON.parse(cleaned);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  } catch (e) {}
  return { description: rawContent.trim() };
}

function stableNumber(value) {
  return String(value || '').split('').reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
}

function cleanProductName(name) {
  return String(name || 'silk scarf')
    .replace(/\s+/g, ' ')
    .replace(/\s+-\s+Herbert Accessory$/i, '')
    .trim();
}

function splitHistory(value) {
  if (!value) return [];
  return String(value).split(/\n---\n|\n(?=20\d\d-\d\d-\d\dT)/).map(s => s.trim()).filter(Boolean);
}

function descriptionKey(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/https?:\/\/\S+/g, '')
    .replace(/#[a-z0-9_]+/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function buildFallbackSet(row, productUrl) {
  const productName = cleanProductName(row.title || row.pin_title || 'silk scarf');
  const imageIndex = Number(row.selected_image_index ?? row.slot_index ?? 0);
  const seed = stableNumber((row.product_id || '') + (row.sku || '') + String(imageIndex));
  const pick = (list, offset = 0) => list[(seed + imageIndex + offset) % list.length];

  const pinterestOpenings = [
    'Save this scarf idea for the next simple outfit that needs one beautiful detail.',
    'This is the kind of silk square that makes a plain shirt feel styled.',
    'A soft print, a clean fold, and suddenly the outfit has a point of view.',
    'Pin this for scarf styling days when you want color without overthinking it.',
    'A pure silk scarf can do a lot of quiet work in a wardrobe.'
  ];
  const instagramOpenings = [
    'Today\'s little styling note: let the scarf do the talking.',
    'A soft silk square, tied simply, changes the whole mood.',
    'This print was made for close-up details and easy everyday outfits.',
    'A small accessory moment, but a very useful one.',
    'Keeping the outfit simple and letting the silk bring the color.'
  ];
  const facebookOpenings = [
    'Here is a gentle styling idea for anyone who loves useful accessories.',
    'This silk scarf is an easy way to refresh pieces you already wear often.',
    'For gifting or everyday styling, a printed silk square is quietly practical.',
    'If you like accessories that earn their place, this scarf is worth a look.',
    'A beautiful scarf does not need a special occasion to be useful.'
  ];
  const bodies = [
    productName + ' has a light pure silk feel, soft movement, and a print that works with shirts, knits, denim, and neutral coats.',
    'Wear ' + productName + ' at the neck, in your hair, or tied to a bag when the outfit needs a softer finish.',
    productName + ' brings pattern and texture without making the look feel heavy or overdone.',
    'The pure silk drape keeps ' + productName + ' polished, but still easy enough for repeat everyday wear.',
    productName + ' is a thoughtful silk scarf gift for someone who likes beautiful pieces they can actually use.'
  ];
  const closers = [
    'Shop now: ' + productUrl,
    'See the scarf here: ' + productUrl,
    'Browse the details: ' + productUrl
  ];
  const hashtags = [
    '#silkscarf #puresilk #scarfstyling #silkscarfstyle #herbertaccessory',
    '#mulberrysilk #printedscarf #scarfoutfitideas #giftforher #herbertaccessory',
    '#luxurysilkscarf #silksquare #elegantaccessories #silkstyle #herbertaccessory'
  ];

  return {
    pinterest: truncate([pick(pinterestOpenings, 0), pick(bodies, 3), pick(closers, 6), pick(hashtags, 9)].join(' '), 800),
    instagram: truncate([pick(instagramOpenings, 1), pick(bodies, 4), pick(closers, 7), pick(hashtags, 10)].join(' '), 800),
    facebook: truncate([pick(facebookOpenings, 2), pick(bodies, 5), pick(closers, 8)].join(' '), 800),
  };
}

function uniquePlatformCopy(row, productUrl, ai) {
  const fallback = buildFallbackSet(row, productUrl);
  const historyKeys = new Set(splitHistory(row.pin_description_history).map(descriptionKey));
  const get = (field, fallbackValue) => {
    const value = truncate(ai[field] || fallbackValue, 800);
    return historyKeys.has(descriptionKey(value)) ? fallbackValue : value;
  };
  return {
    pinterest: get('pinterest_description', get('description', fallback.pinterest)),
    instagram: get('instagram_caption', fallback.instagram),
    facebook: get('facebook_caption', fallback.facebook),
  };
}

return responses.map((item, index) => {
  const source = sources[index]?.json || item.json || {};
  const response = item.json || {};
  const rawContent = response.choices?.[0]?.message?.content || response.content || response.text || response.message?.content || '';
  const ai = parseAiContent(rawContent);
  const productUrl = source.canonical_url || source.url || '';
  const productName = cleanProductName(source.title || 'Luxury Silk Scarf');
  const fallbackTitle = truncate(productName + ' | Luxury Silk Scarf - Herbert Accessory', 100);
  const title = truncate((ai.title && ai.title.trim()) || source.pin_title || fallbackTitle, 100);
  const platform_copy = uniquePlatformCopy(source, productUrl, ai);
  const altText = truncate((source.title || title) + ' product image for Herbert Accessory', 500);
  const utmContentBase = String(source.product_id || source.sku || source.row_number || 'pin')
    .toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  const utmContent = truncate(utmContentBase + '_img_' + String(Number(source.selected_image_index || 0) + 1), 60);

  return {
    json: {
      ...source,
      pin_title: title,
      pin_description: platform_copy.pinterest,
      platform_copy,
      recommended_alt_text: altText,
      primary_keywords: '',
      secondary_keywords: '',
      utm_content: utmContent || 'pin',
      ai_raw_content: rawContent,
      ai_debug_response: JSON.stringify(response).slice(0, 600)
    }
  };
});

const items = $input.all();

function firstText(...values) {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
}

function addUtm(rawUrl, params) {
  const baseUrl = String(rawUrl || '').trim();
  if (!baseUrl) throw new Error('Missing canonical URL for destination.');
  const hashIndex = baseUrl.indexOf('#');
  const withoutHash = hashIndex >= 0 ? baseUrl.slice(0, hashIndex) : baseUrl;
  const hash = hashIndex >= 0 ? baseUrl.slice(hashIndex + 1) : '';
  const queryIndex = withoutHash.indexOf('?');
  const path = queryIndex >= 0 ? withoutHash.slice(0, queryIndex) : withoutHash;
  const existingQuery = queryIndex >= 0 ? withoutHash.slice(queryIndex + 1) : '';
  const queryParts = existingQuery ? existingQuery.split('&').filter(Boolean) : [];
  for (const [key, value] of Object.entries(params)) {
    if (!value) continue;
    queryParts.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(value)));
  }
  return path + (queryParts.length ? '?' + queryParts.join('&') : '') + (hash ? '#' + hash : '');
}

const PARIS_TIME_ZONE = 'Europe/Paris';
function getParisDateParts(date) {
  return new Intl.DateTimeFormat('en-US', { timeZone: PARIS_TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit' })
    .formatToParts(date).reduce((parts, part) => { if (part.type !== 'literal') parts[part.type] = Number(part.value); return parts; }, {});
}
function parisWallTimeToUTC(dateParts, targetParisHour) {
  const utcGuess = new Date(Date.UTC(dateParts.year, dateParts.month - 1, dateParts.day, targetParisHour, 0, 0));
  const slotParts = new Intl.DateTimeFormat('en-US', { timeZone: PARIS_TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })
    .formatToParts(utcGuess).reduce((parts, part) => { if (part.type !== 'literal') parts[part.type] = Number(part.value); return parts; }, {});
  const asUtc = Date.UTC(slotParts.year, slotParts.month - 1, slotParts.day, slotParts.hour, slotParts.minute, slotParts.second);
  return new Date(Date.UTC(dateParts.year, dateParts.month - 1, dateParts.day, targetParisHour, 0, 0) - (asUtc - utcGuess.getTime()));
}
function addParisDays(dateParts, days) {
  return getParisDateParts(new Date(Date.UTC(dateParts.year, dateParts.month - 1, dateParts.day + days, 12, 0, 0)));
}

const SCHEDULE_HOURS_EU = [9, 13, 18];
const now = new Date();
const todayParis = getParisDateParts(now);
const firstSlotToday = parisWallTimeToUTC(todayParis, SCHEDULE_HOURS_EU[0]);
const scheduleDateParts = now.getTime() >= firstSlotToday.getTime() ? addParisDays(todayParis, 1) : todayParis;

const mutation = `mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    ... on PostActionSuccess { post { id text dueAt status channelId assets { id mimeType } error { message } } }
    ... on MutationError { message }
  }
}`;

return items.flatMap((item) => {
  const row = item.json || {};
  const defaultPinterestChannelId = '658d2612c3b752215a86a80d';
  const defaultFacebookChannelId = '658d296dc3b752215a9a9768';
  const defaultInstagramChannelId = '69fee6675c4c051afa286807';
  const defaultPinterestBoardServiceId = '1113937357772186129';
  const pinterestChannelId = firstText(row.pinterest_channel_id, row.buffer_channel_1_id, row.buffer_pinterest_channel_id, defaultPinterestChannelId);
  const facebookChannelId = firstText(row.facebook_channel_id, row.buffer_channel_2_id, row.buffer_facebook_channel_id, defaultFacebookChannelId);
  const instagramChannelId = firstText(row.instagram_channel_id, row.buffer_channel_3_id, row.buffer_instagram_channel_id, defaultInstagramChannelId);
  const boardServiceId = firstText(row.pinterest_board_service_id, row.board_service_id, defaultPinterestBoardServiceId);
  const campaignSlug = firstText(row.campaign_name, 'product-crawl').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  if (!pinterestChannelId) throw new Error('Missing Pinterest Buffer channel ID.');
  if (!facebookChannelId) throw new Error('Missing Facebook Buffer channel ID.');
  if (!instagramChannelId) throw new Error('Missing Instagram Buffer channel ID.');
  if (!boardServiceId) throw new Error('Missing Pinterest board service ID.');

  const slotIndex = Number(row.slot_index || 0);
  const slotInDay = slotIndex % SCHEDULE_HOURS_EU.length;
  const euHour = SCHEDULE_HOURS_EU[slotInDay] ?? SCHEDULE_HOURS_EU[0];
  const slotDateParts = addParisDays(scheduleDateParts, Math.floor(slotIndex / SCHEDULE_HOURS_EU.length));
  const dueAt = parisWallTimeToUTC(slotDateParts, euHour).toISOString();
  const copy = row.platform_copy || {};
  const imageContent = (row.utm_content || 'post') + '_img_' + String(Number(row.selected_image_index || 0) + 1);

  const platforms = [
    { platform: 'pinterest', channelId: pinterestChannelId, text: copy.pinterest || row.pin_description || '', destinationUrl: addUtm(row.canonical_url, { utm_source: 'pinterest', utm_medium: 'social', utm_campaign: campaignSlug, utm_content: imageContent }), metadata: { pinterest: { boardServiceId, title: row.pin_title, url: addUtm(row.canonical_url, { utm_source: 'pinterest', utm_medium: 'social', utm_campaign: campaignSlug, utm_content: imageContent }) } } },
    { platform: 'instagram', channelId: instagramChannelId, text: copy.instagram || row.pin_description || '', destinationUrl: addUtm(row.canonical_url, { utm_source: 'instagram', utm_medium: 'social', utm_campaign: campaignSlug, utm_content: imageContent }), metadata: { instagram: { type: 'post', shouldShareToFeed: true } } },
    { platform: 'facebook', channelId: facebookChannelId, text: copy.facebook || row.pin_description || '', destinationUrl: addUtm(row.canonical_url, { utm_source: 'facebook', utm_medium: 'social', utm_campaign: campaignSlug, utm_content: imageContent }), metadata: { facebook: { type: 'post' } } },
  ];

  return platforms.map(post => ({
    json: {
      ...row,
      buffer_platform: post.platform,
      destination_url: post.destinationUrl,
      scheduled_time_utc: dueAt,
      scheduled_slot_eu: String(euHour).padStart(2, '0') + ':00 Europe/Paris',
      scheduled_date_eu: [slotDateParts.year, String(slotDateParts.month).padStart(2, '0'), String(slotDateParts.day).padStart(2, '0')].join('-'),
      buffer_graphql_body: {
        query: mutation,
        variables: {
          input: {
            schedulingType: 'automatic',
            mode: 'customScheduled',
            dueAt,
            channelId: post.channelId,
            text: post.text,
            assets: [{ image: { url: row.selected_image_url } }],
            metadata: post.metadata,
          }
        }
      }
    }
  }));
});

const rows = $('Code - Build Buffer Payload').all();
const results = $input.all();

function splitUrls(value) {
  if (!value) return [];
  return String(value).split(',').map(s => s.trim()).filter(Boolean);
}

function splitHistory(value) {
  if (!value) return [];
  return String(value).split(/\n---\n|\n(?=20\d\d-\d\d-\d\dT)/).map(s => s.trim()).filter(Boolean);
}

function truncate(text, max) {
  const value = String(text || '').replace(/\s+/g, ' ').trim();
  return value.length > max ? value.slice(0, max - 1).trimEnd() : value;
}

function descriptionKey(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/https?:\/\/\S+/g, '')
    .replace(/#[a-z0-9_]+/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function appendDescriptionHistory(existing, description, when) {
  const history = splitHistory(existing);
  const key = descriptionKey(description);
  const keys = new Set(history.map(descriptionKey));
  if (key && !keys.has(key)) history.push(when + ' ' + truncate(description, 700));
  return history.slice(-30).join('\n---\n');
}

// First pass: extract per-item result
const itemResults = results.map((item, index) => {
  const row = rows[index]?.json || item.json || {};
  const result = item.json || {};
  const action = result.data?.createPost || {};
  const post = action.post || null;
  const graphQLError = Array.isArray(result.errors) ? result.errors.map(e => e.message || JSON.stringify(e)).join('; ') : '';
  const mutationError = action.message || '';
  const postError = post?.error?.message || '';
  const missingPostError = !post ? 'Buffer did not return a created post. Check the Buffer HTTP response, credentials, channel ID, board ID, image URL, and dueAt.' : '';
  const error = graphQLError || mutationError || postError || missingPostError || '';

  return {
    rowNumber: String(row.row_number),
    selectedImageUrl: row.selected_image_url || '',
    allImageUrls: Array.isArray(row.all_image_urls) ? row.all_image_urls : [],
    existingPublished: splitUrls(row.published_image_urls || ''),
    success: !error,
    error,
    post,
    platform: row.buffer_platform || '',
    rowSnapshot: row,
  };
});

// Second pass: group by row_number so multiple images from the same product
// are written to the sheet in a single update (prevents overwrite race).
const rowGroups = new Map();
itemResults.forEach(r => {
  const key = r.rowNumber;
  if (!rowGroups.has(key)) {
    rowGroups.set(key, {
      snapshot: r.rowSnapshot,
      allImageUrls: r.allImageUrls,
      existingPublished: r.existingPublished,
      newlyPublished: [],
      errors: [],
      posts: [],
      descriptions: [],
    });
  }
  const group = rowGroups.get(key);
  // Advance the product image cursor only when the Pinterest post succeeds.
  // Facebook mirrors the same post, but should not move the Pinterest queue by itself.
  if (r.success && r.selectedImageUrl && r.platform === 'pinterest') {
    group.newlyPublished.push(r.selectedImageUrl);
  }
  if (r.error) group.errors.push(r.error);
  if (r.post) group.posts.push(r.post);
  if (r.success && r.platform === 'pinterest' && r.rowSnapshot.pin_description) {
    group.descriptions.push(r.rowSnapshot.pin_description);
  }
});

// Output one item per unique product row
return Array.from(rowGroups.values()).map(group => {
  const allPublished = [...new Set([...group.existingPublished, ...group.newlyPublished])];
  const allImages = group.allImageUrls;
  const allDone = allImages.length > 0 && allImages.every(u => allPublished.includes(u));
  const error = group.errors.filter(Boolean).join('; ');
  const hasSuccess = group.newlyPublished.length > 0;
  const pinStatus = !hasSuccess && error ? 'failed' : (allDone ? 'completed' : 'pending');
  const now = new Date().toISOString();
  const descriptionHistory = group.descriptions.reduce(
    (history, description) => appendDescriptionHistory(history, description, now),
    group.snapshot.pin_description_history || ''
  );
  const lastPost = group.posts[group.posts.length - 1] || null;

  return {
    json: {
      ...group.snapshot,
      pin_status: pinStatus,
      pin_image_url: group.newlyPublished[group.newlyPublished.length - 1] || group.snapshot.pin_image_url || '',
      published_image_urls: allPublished.join(','),
      pin_description_history: descriptionHistory,
      buffer_post_id: lastPost?.id || '',
      buffer_status: lastPost?.status || '',
      buffer_due_at: lastPost?.dueAt || '',
      buffer_error: error,
      last_attempt_at: now,
      posted_at: hasSuccess ? now : '',
      buffer_response_json: JSON.stringify({ posts: group.posts, errors: group.errors }).slice(0, 1200),
    }
  };
});
